import dlt

@dlt.table(comment="Raw claims — bronze layer")
def bronze_claims():
    return (spark.readStream
        .format("cloudFiles")
        .option("cloudFiles.format", "json")
        .option("cloudFiles.schemaLocation",
                "/pipelines/clearcover/schema")
        .load("abfss://raw@clearcoverstorage.dfs.core.windows.net/claims/"))

@dlt.table(comment="Valid claims — silver layer")
@dlt.expect_or_drop(
    "valid_claim_id",
    "claim_id IS NOT NULL AND claim_id LIKE 'CLM-%'"
)
def silver_claims():
    return dlt.read_stream("bronze_claims")

@dlt.table(comment="Gold claims summary for monthly reporting")
@dlt.expect_or_fail(
    "non_null_policy_number",
    "policy_number IS NOT NULL"
)
def gold_claims_summary():
    return (
        dlt.read("silver_claims")
        .groupBy("policy_number", "claim_month")
        .count()
    )

